-- Generated by check_mapping.py from examples/clearing-mapping.csv (postgres). Review before running.
-- Each query returns one row per check; a non-zero 'failing' value needs a look.

-- ===== clr_api_record =====
-- 1. Row counts: source acq_legacy_record vs target clr_api_record (the difference should match the rejection report)
SELECT (SELECT COUNT(*) FROM acq_legacy_record) AS source_rows, (SELECT COUNT(*) FROM clr_api_record) AS target_rows;

-- 2. Key reconciliation on arn (source acq_legacy_record.arn_23)
--    The key is transformed (TRIM(src.arn_23)): apply the same transformation to s.arn_23 below.
SELECT 'missing in target' AS check_name, COUNT(*) AS failing FROM acq_legacy_record s
  WHERE NOT EXISTS (SELECT 1 FROM clr_api_record t WHERE t.arn = s.arn_23)
UNION ALL
SELECT 'not in source', COUNT(*) FROM clr_api_record t
  WHERE NOT EXISTS (SELECT 1 FROM acq_legacy_record s WHERE s.arn_23 = t.arn)
UNION ALL
SELECT 'duplicate key in target', COUNT(*) - COUNT(DISTINCT arn) FROM clr_api_record;

-- 3. Data quality checks on clr_api_record
SELECT check_name, rule, failing FROM (
  SELECT 'arn mandatory' AS check_name, 'DQ-01' AS rule, SUM(CASE WHEN arn IS NULL OR TRIM(CAST(arn AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'arn longer than 23' AS check_name, 'DQ-01' AS rule, SUM(CASE WHEN LENGTH(arn) > 23 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'acquirer_id mandatory' AS check_name, 'DQ-02' AS rule, SUM(CASE WHEN acquirer_id IS NULL OR TRIM(CAST(acquirer_id AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'acquirer_id longer than 6' AS check_name, 'DQ-02' AS rule, SUM(CASE WHEN LENGTH(acquirer_id) > 6 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'merchant_id mandatory' AS check_name, 'DQ-02' AS rule, SUM(CASE WHEN merchant_id IS NULL OR TRIM(CAST(merchant_id AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'merchant_id longer than 15' AS check_name, 'DQ-02' AS rule, SUM(CASE WHEN LENGTH(merchant_id) > 15 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'mcc mandatory' AS check_name, 'DQ-03' AS rule, SUM(CASE WHEN mcc IS NULL OR TRIM(CAST(mcc AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'mcc longer than 4' AS check_name, 'DQ-03' AS rule, SUM(CASE WHEN LENGTH(mcc) > 4 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'pan_token mandatory' AS check_name, 'DQ-04' AS rule, SUM(CASE WHEN pan_token IS NULL OR TRIM(CAST(pan_token AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'pan_token longer than 19' AS check_name, 'DQ-04' AS rule, SUM(CASE WHEN LENGTH(pan_token) > 19 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'amount_minor mandatory' AS check_name, 'DQ-05' AS rule, SUM(CASE WHEN amount_minor IS NULL OR TRIM(CAST(amount_minor AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'currency mandatory' AS check_name, 'DQ-06' AS rule, SUM(CASE WHEN currency IS NULL OR TRIM(CAST(currency AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'currency longer than 3' AS check_name, 'DQ-06' AS rule, SUM(CASE WHEN LENGTH(currency) > 3 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'currency not in allowed values' AS check_name, 'DQ-06' AS rule, SUM(CASE WHEN currency IS NOT NULL AND currency NOT IN ('EUR', 'USD', 'GBP', 'CHF') THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'transaction_date mandatory' AS check_name, 'DQ-07' AS rule, SUM(CASE WHEN transaction_date IS NULL OR TRIM(CAST(transaction_date AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'auth_code mandatory' AS check_name, 'DQ-10' AS rule, SUM(CASE WHEN auth_code IS NULL OR TRIM(CAST(auth_code AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'auth_code longer than 6' AS check_name, 'DQ-10' AS rule, SUM(CASE WHEN LENGTH(auth_code) > 6 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'transaction_type mandatory' AS check_name, 'DQ-08' AS rule, SUM(CASE WHEN transaction_type IS NULL OR TRIM(CAST(transaction_type AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'transaction_type longer than 10' AS check_name, 'DQ-08' AS rule, SUM(CASE WHEN LENGTH(transaction_type) > 10 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'transaction_type not in allowed values' AS check_name, 'DQ-08' AS rule, SUM(CASE WHEN transaction_type IS NOT NULL AND transaction_type NOT IN ('PURCHASE', 'REFUND', 'CASH') THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'entry_mode longer than 12' AS check_name, 'DQ-08' AS rule, SUM(CASE WHEN LENGTH(entry_mode) > 12 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'entry_mode not in allowed values' AS check_name, 'DQ-08' AS rule, SUM(CASE WHEN entry_mode IS NOT NULL AND entry_mode NOT IN ('CHIP', 'CONTACTLESS', 'ECOM', 'MAGSTRIPE', 'MANUAL') THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'merchant_country mandatory' AS check_name, 'DQ-06' AS rule, SUM(CASE WHEN merchant_country IS NULL OR TRIM(CAST(merchant_country AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'merchant_country longer than 2' AS check_name, 'DQ-06' AS rule, SUM(CASE WHEN LENGTH(merchant_country) > 2 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'eci longer than 2' AS check_name, 'DQ-09' AS rule, SUM(CASE WHEN LENGTH(eci) > 2 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'source_format mandatory' AS check_name, '' AS rule, SUM(CASE WHEN source_format IS NULL OR TRIM(CAST(source_format AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM clr_api_record
UNION ALL
  SELECT 'source_format longer than 10' AS check_name, '' AS rule, SUM(CASE WHEN LENGTH(source_format) > 10 THEN 1 ELSE 0 END) AS failing FROM clr_api_record
) c ORDER BY failing DESC;

